from pathlib import Path
import re

root = Path('/workspaces/elements/ui')
stories_root = root / '.storybook' / 'stories'
main_file = root / '.storybook' / 'main.ts'

story_files = sorted(stories_root.rglob('*.stories.tsx'))

def flattened_name(path: Path) -> str:
    stem = path.name
    return stem

name_to_paths = {}
for path in story_files:
    if path.parent == stories_root:
        continue
    name_to_paths.setdefault(flattened_name(path), []).append(path)

resolved_targets = {}
for name, paths in name_to_paths.items():
    if len(paths) == 1:
        resolved_targets[paths[0]] = stories_root / name
        continue
    for path in paths:
        relative_parts = path.relative_to(stories_root).parts[:-1]
        prefix_parts = [part for part in relative_parts if part not in {'elements', 'coda'}]
        prefix = ''.join(part[:1].upper() + part[1:] for part in prefix_parts)
        resolved_targets[path] = stories_root / f'{prefix}{name}'

for path in story_files:
    text = path.read_text()
    text = re.sub(r'title:\s*["\"][^"\"]+/([^"\"]+)["\"]', lambda m: f'title: "elements/{m.group(1)}"', text, count=1)
    path.write_text(text)

main_text = main_file.read_text()
main_text = main_text.replace('stories: ["./stories/elements/**/*.stories.@(js|jsx|mjs|ts|tsx|mdx)", "./stories/coda/**/*.stories.@(js|jsx|mjs|ts|tsx|mdx)"],', 'stories: ["./stories/**/*.stories.@(js|jsx|mjs|ts|tsx|mdx)"],')
main_file.write_text(main_text)

for source, target in resolved_targets.items():
    if target.exists() and target.resolve() != source.resolve():
        raise SystemExit(f'target already exists: {target}')

for source, target in resolved_targets.items():
    target.parent.mkdir(parents=True, exist_ok=True)
    source.rename(target)

for directory in sorted((path for path in stories_root.rglob('*') if path.is_dir()), key=lambda p: len(p.parts), reverse=True):
    try:
        directory.rmdir()
    except OSError:
        pass
